CREATE TABLE IF NOT EXISTS maintenance_reliability_standard_deployment(deployment_id TEXT PRIMARY KEY,standard_id TEXT NOT NULL,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,work_center_id TEXT,period_key TEXT NOT NULL,version_no INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'PROPOSED',deployed_at TIMESTAMP,deployed_by TEXT,acknowledgement_required INTEGER NOT NULL DEFAULT 1,acknowledgement_count INTEGER NOT NULL DEFAULT 0,applicable_count INTEGER NOT NULL DEFAULT 0,adoption_pct NUMERIC NOT NULL DEFAULT 0,exception_count INTEGER NOT NULL DEFAULT 0,evidence_note TEXT,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(standard_id,work_center_id,period_key));
CREATE TABLE IF NOT EXISTS maintenance_reliability_standard_adoption(adoption_id TEXT PRIMARY KEY,deployment_id TEXT NOT NULL,standard_id TEXT NOT NULL,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,work_center_id TEXT,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',acknowledged_at TIMESTAMP,acknowledged_by TEXT,exception_reason TEXT,evidence_note TEXT,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(deployment_id,subject_type,subject_id));
CREATE TABLE IF NOT EXISTS maintenance_reliability_standard_exception(exception_id TEXT PRIMARY KEY,deployment_id TEXT NOT NULL,standard_id TEXT NOT NULL,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,work_center_id TEXT,exception_type TEXT NOT NULL,severity TEXT NOT NULL DEFAULT 'MEDIUM',reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',resolved_by TEXT,resolved_at TIMESTAMP,resolution_note TEXT,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_reliability_standard_deployment_scope ON maintenance_reliability_standard_deployment(organization_id,entity_id,status,work_center_id);
CREATE INDEX IF NOT EXISTS ix_reliability_standard_adoption_scope ON maintenance_reliability_standard_adoption(organization_id,entity_id,status,work_center_id);
CREATE INDEX IF NOT EXISTS ix_reliability_standard_exception_scope ON maintenance_reliability_standard_exception(organization_id,entity_id,status,severity,work_center_id);
